import itertools

def get_sign(perm):
    n = len(perm)
    inversions = 0
    for i in range(n):
        for j in range(i + 1, n):
            if perm[i] > perm[j]:
                inversions += 1
    return 1 if inversions % 2 == 0 else -1

def count_fixed_points(perm):
    return sum(1 for i, p in enumerate(perm) if p == i + 1)

def calculate_L_N(N):
    S_N = list(itertools.permutations(range(1, N + 1)))
    L_N = 0
    for pi in S_N:
        sigma = get_sign(pi)
        v_pi = count_fixed_points(pi)
        L_N += sigma / (v_pi + 1)
    return L_N

L5 = calculate_L_N(5)
